62				var viewer = new Wipeout('container', window.innerWidth, window.innerHeight);
63	
64				// Build the Scene Selection Dropdown
65				var loadingFunctions = [];
66				var select = document.getElementById('sceneSelect');
67	
68				select.addEventListener('change', function(ev){
69					var idx = ev.currentTarget.value;
70					loadingFunctions[idx](viewer);
71				}, true);
