73				var addGroup = function(parent, name) {
74					var group = document.createElement('optgroup');
75					group.label = name;
76					parent.appendChild(group);
77					return group;
78				}
79	
80				var addOption = function(parent, name, func) {
81					var option = document.createElement('option');
82					option.value = loadingFunctions.length;
83					option.innerHTML = name;
84					parent.appendChild(option);
85					
86					loadingFunctions.push(func);
87				};
