89	
90				// WipEout
91				var groupWipeout = addGroup(select, 'WipEout');
92	
93				for( var i = 0; i < Wipeout.Tracks.Wipeout.length; i++ ) {
94					var track = Wipeout.Tracks.Wipeout[i];
95	
96					addOption(groupWipeout, track.name, (function(track, viewer){
97						viewer.clear();
98						viewer.loadTrack(track.path, track.hasTEXFile);
99					}).bind(null, track));
100				}
