2	var Wipeout = function(containerId, width, height){
3		this.renderer = new THREE.WebGLRenderer( { antialias: true } );
4		this.renderer.setSize( width, height );
5		this.renderer.setClearColor( 0x000000 );
6		this.container = document.getElementById( containerId );
7		this.container.appendChild( this.renderer.domElement );
8		this.width = width;
9		this.height = height;
10	
11		this.activeCameraMode = 'fly';
12	
13		window.addEventListener('resize', this.resize.bind(this), true);
14		this.clear();
15		this.animate();
16	};
17	
18	Wipeout.prototype.clear = function() {
19		this.clock = new THREE.Clock();
20		this.scene = new THREE.Scene();
21		this.sprites = [];
22	
23		// Add Camera and controls for orbit
24		this.camera = new THREE.PerspectiveCamera( 45, this.width / this.height, 64, 2048576 );
25		this.camera.position.set( 0, 10000, 50000 );
26		this.camera.rotation.order = 'YZX';
27	
28		this.controls = new THREE.FirstPersonControls(this.camera, this.renderer.domElement);
29		this.controls.movementSpeed = 16000.0;
30		// this.controls.damping = 0.2;
31		// this.controls.zoomSpeed = 2;
32	
33		// Add Camera for fly through
34		this.splineCamera = new THREE.PerspectiveCamera( 84, window.innerWidth / window.innerHeight, 64, 2048576 );
35		this.splineCamera.currentLookAt = new THREE.Vector3(0,0,0);
36		this.splineCamera.roll = 0;
37		this.splineCamera.rotation.order = 'YZX';
38	
39		this.cameraSpline = null;
40		this.sceneMaterial = {};
41		this.trackMaterial = null;
42		this.weaponTileMaterial = null;
43		
44		this.startTime = Date.now();
45		this.ticks = 0;
46	};
47	
48	Wipeout.prototype.resize = function() {
49		this.width = window.innerWidth;
50		this.height = window.innerHeight;
51		
52		this.camera.aspect = this.width / this.height;
53		this.camera.updateProjectionMatrix();
54	
55		this.splineCamera.aspect = this.width / this.height;
56		this.splineCamera.updateProjectionMatrix();	
57	
58		this.renderer.setSize( window.innerWidth, window.innerHeight );
59	}
60	
61	Wipeout.prototype.animate = function() {
62		requestAnimationFrame( this.animate.bind(this) );
63		var time = Date.now();
64		
65		// Update weapon tile color 
66		if(this.weaponTileMaterial) {
67			this.updateWeaponMaterial(time);
68		}
69	
70		// Camera is in fly mode and we have a spline to follow?
71		if( this.activeCameraMode === 'fly' && this.cameraSpline ) {
72		
73			var elapsedTime = time - this.startTime;
74			var elapsedTicks = elapsedTime / 1000 * 60;
75	
76			// Fixed time step loop (60hz)
77			while(this.ticks < elapsedTicks) {
78			
79				this.updateSplineCamera();
80				this.ticks++;
81			}
82			
83			this.rotateSpritesToCamera(this.splineCamera);
84			this.renderer.render(this.scene, this.splineCamera);
85		}
86	
87		// Default Orbit camera
88		else {
89			this.controls.update(this.clock.getDelta());
90			this.rotateSpritesToCamera(this.camera);
91			this.renderer.render( this.scene, this.camera );
92		}
93	};
94	
95	Wipeout.prototype.updateSplineCamera = function() {
96		var damping = 0.90;
97		var time = this.ticks * 1000 / 60;
98	
99		var loopTime = this.cameraSpline.points.length * 100;
100	
101		// Camera position along the spline
102		var tmod = ( time % loopTime ) / loopTime;
103		var cameraPos = this.cameraSpline.getPointAt( tmod ).clone();
104		this.splineCamera.position.multiplyScalar(damping)
105			.add(cameraPos.clone().add({x:0, y:600, z:0}).multiplyScalar(1-damping));
106	
107		// Camera lookAt along the spline
108		var tmodLookAt = ( (time+800) % loopTime ) / loopTime;
109		var lookAtPos = this.cameraSpline.getPointAt( tmodLookAt ).clone();
110		this.splineCamera.currentLookAt = this.splineCamera.currentLookAt.multiplyScalar(damping)
111			.add(lookAtPos.clone().multiplyScalar(1-damping));
112		this.splineCamera.lookAt(this.splineCamera.currentLookAt);
113	
114		// Roll into corners - there's probably an easier way to do this. This 
115		// takes the angle between the current camera position and the current
116		// lookAt, applies some damping and rolls the camera along its view vector
117		var cn = cameraPos.sub(this.splineCamera.position);
118		var tn = lookAtPos.sub(this.splineCamera.currentLookAt);
119		var roll = (Math.atan2(cn.z, cn.x) - Math.atan2(tn.z, tn.x));
120		roll += (roll > Math.PI)
121			? -Math.PI*2 
122			: (roll < -Math.PI) ? Math.PI * 2 : 0;
123	
124		this.splineCamera.roll = this.splineCamera.roll * 0.95 + (roll)*0.1;
125		this.splineCamera.up = (new THREE.Vector3(0,1,0)).applyAxisAngle(
126			this.splineCamera.position.clone().sub(this.splineCamera.currentLookAt).normalize(),
127			this.splineCamera.roll * 0.25
128		);
129	}
130	
131	
132	Wipeout.prototype.rotateSpritesToCamera = function(camera) {
133		for( var i = 0; i < this.sprites.length; i++ ) {
134			this.sprites[i].rotation.y = camera.rotation.y;
135		}
136	};
137	
138	Wipeout.prototype.updateWeaponMaterial = function(time) {
139		// Purple -> blue -> cyan -> yellow -> amber (never 100% red or green)
140		var colors = [0x800080, 0x0000ff, 0x00ffff, 0xffff00, 0xff8000];
141		var t = time / 1050;
142		var index = Math.floor(t);
143		var alpha = t - index;
144		
145		var colorA = new THREE.Color(colors[index%colors.length]);
146		var colorB = new THREE.Color(colors[(index+1)%colors.length]);
147		this.weaponTileMaterial.color = colorA.lerp(colorB, alpha).multiplyScalar(1.5);
148	};
