398	// Utility Functions to load a binary buffer via AJAX
399	
400	Wipeout.prototype.loadBinary = function(url, callback) {
401		var req = new XMLHttpRequest();
402		req.open("GET", url, true);
403		req.responseType = "arraybuffer";
404	
405		if( req.overrideMimeType ) {
406			req.overrideMimeType('text/plain; charset=x-user-defined');
407		} 
408		else {
409			req.setRequestHeader('Accept-Charset', 'x-user-defined');
410		}
411	
412		req.onload = function(ev) {
413			if( req.status == 200 ) {
414				callback(req.response);
415			}
416		};
417		req.send();
418	};
