420	Wipeout.prototype.loadBinaries = function(urls, callback) {
421		var files = {};
422		var pending = 0;
423		for( var name in urls ) {
424			pending++;
425		}
426	
427		var that = this;
428		for( var name in urls ) {
429	
430			(function( name, url ){
431				that.loadBinary(url, function(buffer) {
432					files[name] = buffer;
433					pending--;
434					if( pending === 0 ) {
435						callback(files);
436					}
437				});
438			})(name, urls[name]);
439	
440		}
441	};
