449	// Read 3D Objects from a PRM File
450	
451	Wipeout.prototype.readObjects = function(buffer) {
452		var offset = 0;
453		var objects = [];
454		while( offset < buffer.byteLength ) {
455			var object = this.readObject(buffer, offset);
456			offset += object.byteLength;
457			objects.push(object);
458		}
459	
460		return objects;
461	};
