463	Wipeout.prototype.readObject = function(buffer, offset) {
464		var initialOffset = offset;
465	
466		var header = Wipeout.ObjectHeader.readStructs(buffer, offset, 1)[0];
467		offset += Wipeout.ObjectHeader.byteLength;
468		
469		var vertices = Wipeout.Vertex.readStructs(buffer, offset, header.vertexCount);
470		offset += Wipeout.Vertex.byteLength * header.vertexCount;
471	
472		var polygons = [];
473		for( var i = 0; i < header.polygonCount; i++ ) {
474			// Peek into the header first to select the right Polygon type
475			var polygonHeader = Wipeout.PolygonHeader.readStructs(buffer, offset, 1)[0];
476	
477			var PolygonType = Wipeout.Polygon[polygonHeader.type];
478			var polygon = PolygonType.readStructs(buffer, offset, 1)[0];
479			offset += PolygonType.byteLength;
480	
481			polygons.push(polygon);
482		}
483	
484		return {
485			header: header,
486			vertices: vertices,
487			polygons: polygons,
488			byteLength: offset - initialOffset
489		};
490	};
