493	// ----------------------------------------------------------------------------
494	// Create a ThreeJS Model from a single PRM 3D Object
495	
496	Wipeout.prototype.createModelFromObject = function(object, spriteCollection) {
497		var model = new THREE.Object3D();
498		var geometry = new THREE.Geometry();
499	
500		model.position.set(object.header.position.x, -object.header.position.y, -object.header.position.z);
501	
502		// Load vertices
503		for( var i = 0; i < object.vertices.length; i++ ) {
504			geometry.vertices.push( new THREE.Vector3(object.vertices[i].x, -object.vertices[i].y, -object.vertices[i].z) );
505		}
506	
507		var whiteColor = new THREE.Color(1,1,1);
508		var nullVector = new THREE.Vector2(0, 0);
509	
510		// Create faces
511		for( var i = 0; i < object.polygons.length; i++ ) {
512			var p = object.polygons[i];
513			
514			// Sprite
515			if(
516				p.header.type === Wipeout.POLYGON_TYPE.SPRITE_BOTTOM_ANCHOR ||
517				p.header.type === Wipeout.POLYGON_TYPE.SPRITE_TOP_ANCHOR 
518			) {
519				var v = geometry.vertices[p.index];
520				var color = this.int32ToColor( p.color );
521				var yOffset = p.header.type === Wipeout.POLYGON_TYPE.SPRITE_BOTTOM_ANCHOR 
522					? p.height/2 
523					: -p.height/2;
524	
525				// We can't use THREE.Sprite here, because they rotate to the camera on
526				// all axis. We just want rotation around the Y axis, so we do it manually.
527				var spriteMaterial = new THREE.MeshBasicMaterial({map: this.sceneMaterial.materials[p.texture].map, color: color, alphaTest:0.5});
528				var spriteMesh = new THREE.Mesh( new THREE.PlaneBufferGeometry(p.width, p.height), spriteMaterial );
529	
530				var sprite = new THREE.Object3D();
531				sprite.position.set(v.x, v.y + yOffset, v.z);
532				sprite.add( spriteMesh );
533				model.add(sprite);
534	
535				// We have to collect sprites separately, so we can go through all of them 
536				// and rotate them to the camera before rendering the frame
537				spriteCollection.push( sprite );
538			}
539	
540			// Tris or Quad
541			else if( p.indices ) {
542				var materialIndex = this.sceneMaterial.flatMaterialIndex;
543				var c = [whiteColor, whiteColor, whiteColor, whiteColor];
544				var uv = [nullVector, nullVector, nullVector, nullVector];
545	
546				// Textured
547				if( typeof(p.texture) !== 'undefined' ) {
548					materialIndex = p.texture;
549					
550					var img = this.sceneMaterial.materials[materialIndex].map.image;
551					for( var j = 0; j < p.uv.length; j++ ) {
552						uv[j] = new THREE.Vector2(p.uv[j].u/img.width, 1-p.uv[j].v/img.height);
553					}
554				}
555	
556				// Face or Vertex color?
557				if( p.color || p.colors ) {
558					for( var j = 0; j < p.indices.length; j++ ) {
559						c[j] = this.int32ToColor( p.color || p.colors[j] );
560					}
561				}
562	
563				geometry.faceVertexUvs[0].push([uv[2], uv[1], uv[0]]);
564				geometry.faces.push( new THREE.Face3(p.indices[2], p.indices[1], p.indices[0], null, [c[2], c[1], c[0]], materialIndex) );
565	
566				// Push extra UV and Face for Quads
567				if( p.indices.length === 4 ) {
568					geometry.faceVertexUvs[0].push([uv[2], uv[3], uv[1]]);
569					geometry.faces.push( new THREE.Face3(p.indices[2], p.indices[3], p.indices[1], null, [c[2], c[3], c[1]], materialIndex) );
570				}			
571			}
572		}
573	
574		if( geometry.faces.length ) {
575			var mesh = new THREE.Mesh(geometry, this.sceneMaterial);
576			model.add(mesh);
577		}
578		return model;
579	};
