582	// ----------------------------------------------------------------------------
583	// Unpack TIM images from a compressed CMP File (LZ77)
584	
585	Wipeout.prototype.unpackImages = function(buffer) {
586		var data = new DataView(buffer);
587	
588		// Read the file header
589		var numberOfFiles = data.getUint32(0, true);
590		var packedDataOffset = (numberOfFiles+1)*4;
591	
592		var unpackedLength = 0;
593		for( var i = 0; i < numberOfFiles; i++ ) {
594			unpackedLength += data.getUint32((i+1)*4, true);
595		}
596	
597	
598		// Unpack
599		var src = new Uint8Array(buffer, packedDataOffset);
600		var dst = new Uint8Array(unpackedLength);
601		var wnd = new Uint8Array(0x2000);
602	
603		var srcPos = 0,
604			dstPos = 0,
605			wndPos = 1,
606			curBit = 0,
607			curByte = 0,
608			bitMask = 0x80;
609	
610		var readBitfield = function( size ) {
611			var value = 0;
612			while( size > 0 ) {
613				if( bitMask === 0x80 ) {
614					curByte = src[srcPos++];
615				}
616	
617				if( curByte & bitMask ) {
618					value |= size;
619				}
620	
621				size >>= 1;
622	
623				bitMask >>= 1;
624				if( bitMask === 0 ) {
625					bitMask = 0x80;
626				}
627			}
628	
629			return value;
630		};
631	
632		while( true ) {
633			if( srcPos > src.byteLength || dstPos > unpackedLength ) {
634				break;
635			}
636	
637			if( bitMask === 0x80 ) {
638				curByte = src[srcPos++];
639			}
640	
641			curBit = (curByte & bitMask);
642	
643			bitMask >>= 1;
644			if( bitMask === 0 ) {
645				bitMask = 0x80;
646			}
647	
648			if( curBit ) {
649				wnd[wndPos & 0x1fff] = dst[dstPos] = readBitfield(0x80);
650				wndPos++;
651				dstPos++;
652			}
653			else {
654				var position = readBitfield(0x1000);
655				if( position === 0 ) {
656					break;
657				}
658	
659				var length = readBitfield(0x08)+2;
660				for( var i = 0; i <= length; i++ ) {
661					wnd[wndPos & 0x1fff] = dst[dstPos] = wnd[(i + position) & 0x1fff];
662					wndPos++;
663					dstPos++;
664				}
665			}
666		}
667	
668		// Split unpacked data into separate buffer for each file
669		var fileOffset = 0;
670		var files = [];
671		for( var i = 0; i < numberOfFiles; i++ ) {
672			var fileLength = data.getUint32((i+1)*4, true);
673			files.push( dst.buffer.slice(fileOffset, fileOffset + fileLength) );
674			fileOffset += fileLength;
675			
676		}
677	
678		return files;
679	};
