682	// ----------------------------------------------------------------------------
683	// Render a TIM image into a 2D canvas
684	
685	Wipeout.prototype.readImage = function(buffer) {
686		var data = new DataView(buffer);
687		var file = Wipeout.ImageFileHeader.readStructs(buffer, 0, 1)[0];
688		var offset = Wipeout.ImageFileHeader.byteLength;
689	
690		var palette = null;
691		if( 
692			file.type === Wipeout.IMAGE_TYPE.PALETTED_4_BPP ||
693			file.type === Wipeout.IMAGE_TYPE.PALETTED_8_BPP
694		) {
695			palette = new Uint16Array(buffer, offset, file.paletteColors);
696			offset += file.paletteColors * 2;
697		}
698		offset += 4; // skip data size
699	
700		var pixelsPerShort = 1;
701		if( file.type === Wipeout.IMAGE_TYPE.PALETTED_8_BPP ) {
702			pixelsPerShort = 2;
703		}
704		else if( file.type === Wipeout.IMAGE_TYPE.PALETTED_4_BPP ) {
705			pixelsPerShort = 4;
706		}
707	
708		var dim = Wipeout.ImagePixelHeader.readStructs(buffer, offset, 1)[0];
709		offset += Wipeout.ImagePixelHeader.byteLength;
710		
711		var width = dim.width * pixelsPerShort,
712			height = dim.height;
713	
714		var canvas = document.createElement('canvas');
715		canvas.width = width;
716		canvas.height = height;
717		var ctx = canvas.getContext('2d');
718		var pixels = ctx.createImageData(width, height);
719	
720		var putPixel = function(dst, offset, color) {
721			dst[offset + 0] = (color & 0x1f) << 3; // R
722			dst[offset + 1] = ((color >> 5) & 0x1f) << 3; // G
723			dst[offset + 2] = ((color >> 10) & 0x1f) << 3; // B
724			dst[offset + 3] = color === 0 ? 0 : 0xff; // A
725		}
726	
727		var entries = dim.width * dim.height;
728		if( file.type === Wipeout.IMAGE_TYPE.TRUE_COLOR_16_BPP ) {
729			for( var i = 0; i < entries; i++ ) {
730				var c = data.getUint16(offset+i*2, true);
731				putPixel(pixels.data, i*4, c);
732			}
733		}
734		else if( file.type === Wipeout.IMAGE_TYPE.PALETTED_8_BPP ) {
735			for( var i = 0; i < entries; i++ ) {
736				var p = data.getUint16(offset+i*2, true);
737	
738				putPixel(pixels.data, i*8+0, palette[ p & 0xff ]);
739				putPixel(pixels.data, i*8+4, palette[ (p>>8) & 0xff ]);
740			}
741		}
742		else if( file.type === Wipeout.IMAGE_TYPE.PALETTED_4_BPP ) {
743			for( var i = 0; i < entries; i++ ) {
744				var p = data.getUint16(offset+i*2, true);
745	
746				putPixel(pixels.data, i*16+ 0, palette[ p & 0xf ]);
747				putPixel(pixels.data, i*16+ 4, palette[ (p>>4) & 0xf ]);
748				putPixel(pixels.data, i*16+ 8, palette[ (p>>8) & 0xf ]);
749				putPixel(pixels.data, i*16+12, palette[ (p>>12) & 0xf ]);
750			}
751		}
752	
753		ctx.putImageData(pixels, 0, 0);
754		return canvas;
755	};
