758	// ----------------------------------------------------------------------------
759	// Create a single ThreeJS MeshFaceMaterial with the given images
760	
761	Wipeout.prototype.createMeshFaceMaterial = function(images, vertexColors, side){
762		var materials = [];
763		var basicMaterial = new THREE.MeshBasicMaterial({wireframe:false});
764		basicMaterial.vertexColors = vertexColors;
765	
766		for( var i = 0; i < images.length; i++ ) {
767			var material = basicMaterial;
768	
769			if( images[i].byteLength !== 0 ) {
770				var texture = new THREE.Texture(images[i]);
771				texture.minFilter = THREE.NearestFilter;
772				texture.magFilter = THREE.NearestFilter;
773				texture.needsUpdate = true;	
774				
775				material = new THREE.MeshBasicMaterial({map:texture});
776				
777				if( i === 3 && vertexColors === THREE.FaceColors ) {
778					//this is weapon tile. store material, so we can update color later
779					material.vertexColors = THREE.NoColors;
780					this.weaponTileMaterial = material;
781				}
782				else {
783					material.vertexColors = vertexColors;
784				}
785				
786				
787				material.side = side;
788				material.alphaTest = 0.5;
789			}
790	
791			materials.push(material);
792		}
793		
794		materials.push(basicMaterial)-1;
795		
796		var faceMat = new THREE.MeshFaceMaterial(materials);
797		faceMat.flatMaterialIndex = materials.length-1;
798	
799		return faceMat;
800	};
