804	// Add objects from the PRM and CMP files to the scene
805	
806	Wipeout.prototype.createScene = function(files, modify) {
807		var rawImages = files.textures ? this.unpackImages(files.textures) : [];
808		var images = rawImages.map(this.readImage.bind(this));
809	
810		this.sceneMaterial = this.createMeshFaceMaterial(images, THREE.VertexColors, THREE.FrontSide);
811	
812		var objects = this.readObjects(files.objects);
813		for( var i = 0; i < objects.length; i++ ) {
814			var model = this.createModelFromObject(objects[i], this.sprites);
815			if( modify && modify.scale ) {
816				model.scale.set(modify.scale, modify.scale, modify.scale);
817			}
818			if( modify && modify.move ) {
819				model.position.add(modify.move);
820			}
821			if( modify && modify.space ) {
822				model.position.add({x: (i + 0.5 - objects.length/2)*modify.space, y:0, z: 0});
823			}
824			this.scene.add( model );
825		}
826	};
