829	// ----------------------------------------------------------------------------
830	// Add a track from TRV, TRF, CMP and TTF files to the scene
831	
832	Wipeout.prototype.createTrack = function(files) {
833		var rawImages = this.unpackImages(files.textures);
834		var images = rawImages.map(this.readImage.bind(this));
835	
836		// Load Track Texture Index
837		var indexEntries = files.textureIndex.byteLength / Wipeout.TrackTextureIndex.byteLength;
838		var textureIndex = Wipeout.TrackTextureIndex.readStructs(files.textureIndex, 0, indexEntries);
839	
840		// Extract the big (near) versions of these textures only. The near 
841		// version is composed of 4x4 32px tiles.
842		var composedImages = [];
843		for( var i = 0; i < textureIndex.length; i++ ) {
844			var idx = textureIndex[i];
845			
846			var composedImage = document.createElement('canvas');
847			composedImage.width = 128;
848			composedImage.height = 128;
849			var ctx = composedImage.getContext('2d');
850	
851			for( var x = 0; x < 4; x++ ) {
852				for( var y = 0; y < 4; y++ ) {
853					var image = images[idx.near[y * 4 + x]];
854					ctx.drawImage(image, x*32, y*32)
855				}
856			}
857			composedImages.push(composedImage);
858		}
859	
860	
861		this.trackMaterial = this.createMeshFaceMaterial(composedImages, THREE.FaceColors, THREE.DoubleSide);
862	
863		var model = new THREE.Object3D();
864		var geometry = new THREE.Geometry();
865	
866	
867		// Load vertices
868		var vertexCount = files.vertices.byteLength / Wipeout.TrackVertex.byteLength;
869		var rawVertices = Wipeout.TrackVertex.readStructs(files.vertices, 0, vertexCount);
870	
871		for( var i = 0; i < rawVertices.length; i++ ) {
872			geometry.vertices.push( new THREE.Vector3(rawVertices[i].x, -rawVertices[i].y, -rawVertices[i].z) );
873		}
874	
875		// Load Faces
876		var faceCount = files.faces.byteLength / Wipeout.TrackFace.byteLength;
877		var faces = Wipeout.TrackFace.readStructs(files.faces, 0, faceCount);
878		
879		// Load track texture file (WO2097/WOXL only)
880		if( files.trackTexture ) {
881			var trackTextureCount = files.trackTexture.byteLength / Wipeout.TrackTexture.byteLength;
882			var trackTextures = Wipeout.TrackTexture.readStructs(files.trackTexture, 0, trackTextureCount);
883		
884			// Copy data from TEX to TRF structure
885			for( var i = 0; i < faces.length; i++ ) {
886				var f = faces[i];
887				var t = trackTextures[i];
888				
889				f.tile = t.tile;
890				f.flags = t.flags;
891			}
892		}
893	
894		for( var i = 0; i < faces.length; i++ ) {
895			var f = faces[i];
896	
897			var color = this.int32ToColor( f.color );
898			var materialIndex = f.tile;
899			
900			if(f.flags & Wipeout.TrackFace.FLAGS.BOOST)
901			{
902				//render boost tile as bright blue
903				color = new THREE.Color(0.25, 0.25, 2);
904			}
905			
906			geometry.faces.push( new THREE.Face3(f.indices[0], f.indices[1], f.indices[2], null, color, materialIndex) );
907			geometry.faces.push( new THREE.Face3(f.indices[2], f.indices[3], f.indices[0], null, color, materialIndex) );
908	
909			var flipx = (f.flags & Wipeout.TrackFace.FLAGS.FLIP) ? 1: 0;
910			geometry.faceVertexUvs[0].push([
911				new THREE.Vector2(1-flipx, 1),
912				new THREE.Vector2(0+flipx, 1),
913				new THREE.Vector2(0+flipx, 0)
914			]);
915			geometry.faceVertexUvs[0].push([
916				new THREE.Vector2(0+flipx, 0), 
917				new THREE.Vector2(1-flipx, 0), 
918				new THREE.Vector2(1-flipx, 1)
919			]);
920		}
921	
922		var mesh = new THREE.Mesh(geometry, this.trackMaterial);
923		model.add(mesh);
924		this.scene.add( model );
925	
926	
927		this.createCameraSpline(files.sections, faces, geometry.vertices);
928	};
