931	// ----------------------------------------------------------------------------
932	// Extract a camera from the track section file (.TRS)
933	
934	Wipeout.prototype.createCameraSpline = function(buffer, faces, vertices) {
935		var sectionCount = buffer.byteLength / Wipeout.TrackSection.byteLength;
936		var sections = Wipeout.TrackSection.readStructs(buffer, 0, sectionCount);
937	
938		var cameraPoints = [];
939		var jumpIndexes = [];
940	
941		// First curve, always skip junctions
942		var index = 0;
943		do {
944			var s = sections[index];
945			if(s.flags & Wipeout.TrackSection.FLAGS.JUMP)
946				jumpIndexes.push(cameraPoints.length);
947			
948			var pos = this.getSectionPosition(s, faces, vertices);
949			cameraPoints.push(pos);
950			
951			index = s.next;
952		} while(index > 0 && index < sections.length);
953		
954		// Second curve, take junctions when possible
955		index = 0;
956		do {
957			var s = sections[index];
958			if(s.flags & Wipeout.TrackSection.FLAGS.JUMP)
959				jumpIndexes.push(cameraPoints.length);
960			
961			var pos = this.getSectionPosition(s, faces, vertices);
962			cameraPoints.push(pos);
963			
964			// Get next section, look for junctions
965			if(s.nextJunction != -1 && (sections[s.nextJunction].flags & Wipeout.TrackSection.FLAGS.JUNCTION_START)) {
966				index = s.nextJunction;
967			}
968			else {
969				index = s.next;
970			}
971		} while(index > 0 && index < sections.length);
972		
973		//extend path near jumps by adding tangent vector
974		for(var i = 0 ; i < jumpIndexes.length ; i++ ) {
975			var index = jumpIndexes[i];
976			
977			var jumpPoint = cameraPoints[index];
978			var tangent = jumpPoint.clone().sub(cameraPoints[(index+cameraPoints.length-1)%cameraPoints.length]);
979			var lengthNext = cameraPoints[(index+1)%cameraPoints.length].clone().sub(jumpPoint).length();
980			
981			jumpPoint.add(tangent.setLength(lengthNext/4));
982		}
983		
984		this.cameraSpline = new THREE.HermiteCurve3(cameraPoints, 0.5, 0.0);
985		
986		// Increase arc length subdivisions to get constant camera speed during jumps.
987		// This prevent camera going too fast due imprecise length distance estimations.
988		this.cameraSpline.__arcLengthDivisions = 20000;
989	
990		// Draw the Camera Spline
991		// this.scene.add( new THREE.Mesh(
992		// 	new THREE.TubeGeometry(this.cameraSpline, cameraPoints.length, 50, 5, true), 
993		// 	new THREE.MeshBasicMaterial({color: 0xff00ff})
994		// ));
995	};
