998	// ----------------------------------------------------------------------------
999	// Get track section center position from track vertices
1000	
1001	Wipeout.prototype.getSectionPosition = function(section, faces, vertices) {
1002		var verticescount = 0;
1003		var position = new THREE.Vector3();
1004		for(var i = section.firstFace; i < section.firstFace+section.numFaces; i++ ) {
1005			var face = faces[i];
1006			if (face.flags & Wipeout.TrackFace.FLAGS.TRACK) {
1007				for(var j = 0 ; j < face.indices.length ; j++) {
1008					var vertex = vertices[face.indices[j]];
1009					position.add(vertex);
1010					verticescount++;
1011				}
1012			}
1013		}
1014		
